mapper.select:
SELECT TT.QUOTE_ID, case when T3.QUOTE_ID IS NOT NULL THEN T3.ENTRUST_ID ELSE TT.ENTRUST_ID END ENTRUST_ID, case when T3.QUOTE_ID IS NOT NULL THEN 'Y' ELSE 'N' END isDzh, TT.EXECID, TT.PORTFOLIO_ID, CASE WHEN T3.QUOTE_ID IS NOT NULL OR TT.ENTRUST_ID IS NOT NULL THEN '01' ELSE ( CASE WHEN TT.QUOTE_ID IS NOT NULL THEN '02' ELSE '03' END ) END quoteIdFlag FROM ( SELECT T1.QUOTE_ID , T1.ENTRUST_ID, T2.EXECID, T1.PORTFOLIO_ID FROM IBU_QUOTE_BOND T1 LEFT JOIN IBU_QUOTE_BOND_DET T2 ON T2.QUOTE_ID = T1.QUOTE_ID
T2.EXECID = #{execId}
UNION ALL SELECT T1.QUOTE_ID, T1.ENTRUST_ID , T1.EXECID , T1.PORTFOLIO_ID FROM IBU_QUOTE_CREP T1
T1.EXECID = #{execId}
) TT LEFT JOIN ( SELECT QUOTE_ID, LISTAGG(ENTRUST_ID, ',') WITHIN GROUP (order by (QUOTE_ID)) ENTRUST_ID FROM IBU_QUOTE_ETR_RE GROUP BY QUOTE_ID ) T3 ON T3.QUOTE_ID = TT.QUOTE_ID

SELECT T1.ENTRUST_ID, T1.PORTFOLIO_ID, T1.CCY, T1.FINPROD_TYPE2, T1.TRADE_MARKET, T1.ENTRUST_AMT, T1.ENTRUST_NUM, T2.FINISH_AMT, (NVL(T1.ENTRUST_NUM, T1.ENTRUST_AMT)-NVL(T2.FINISH_AMT, 0)) availableNum FROM ETR_ENTRUST T1 LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID WHERE T1.TRADE_MARKET = '01'
AND ((T1.PRICE_MODEL = 'PRM01' AND T1.PRICE = #{price})
OR (T1.PRICE_MODEL = 'PRM02' AND T1.PRICE >= #{price})
OR (T1.PRICE_MODEL = 'PRM02' AND T1.PRICE <= #{price})
OR T1.PRICE_MODEL = 'PRM03' )
AND T1.VDATE <= TO_DATE(#{dealDate},'YYYY-MM-DD') AND T1.MDATE >= TO_DATE(#{dealDate},'YYYY-MM-DD')
AND T1.FINPROD_ID = #{finprodId}
AND T1.FINPROD_TYPE2 = #{finprodType2}
AND T1.PS = #{ps}
AND T1.PORTFOLIO_ID IN ( SELECT DISTINCT B.PORTFOLIO_ID FROM PTL_SEC_ACCT B, STL_SEC_ACCT_INFO C where B.ACCT_NO in
#{item}
)
AND T1.PORTFOLIO_ID = #{portfolioId}
and T1.ENTRUST_ID in
#{item}
ORDER BY availableNum DESC,CREATE_TIME ASC
